import {faceCrop,detectFaces,facePixels} from './smart-photo.mjs';
import {picture,textLines} from './visual-export.mjs';
export const artworkTypes=[['urgent','عاجل'],['promotion','ترقية'],['achievement','إنجاز عائلي'],['death','البقاء لله'],['graduation','تخرج'],['newborn','مولود جديد'],['quran','ختمة قرآن'],['quran-qr','ختمة قرآن · مع رموز التواصل'],['hospital','على السرير الأبيض'],['recovery','خروج من المشفى'],["family", "خبر عائلي"],["mansoura", "أخبار المنصورة"],["marriage", "عقد قران"],["icu", "في العناية المركزة"],["honor", "تكريم"],["ramadan", "مسابقة أخبار العائلة الرمضانية"],["wedding", "حفل زفاف"],["job", "وظيفة"],["funeral", "وقت التشييع"]];
export function artworkKey(post){return artworkTypes.some(([k])=>k===post.news_artwork)?post.news_artwork:null}
export function artworkLayout(hasPhoto,key,saved){if(saved?.text&&saved?.photo&&['left','center','right'].includes(saved.align))return saved;const height=['honor','job'].includes(key)?295:365;return{align:'right',photo:{x:70,y:225,width:310,height:388},text:hasPhoto?{x:420,y:225,width:590,height}:{x:100,y:230,width:880,height}}}
// Compose supplied artwork on-device. Originals remain separate album slides.
export async function newsArtworkCanvas(post,{signedImage,image=null}={}){
 const key=artworkKey(post);if(!key)return null;const background=await picture('/news-artwork/'+key+'.png'),canvas=document.createElement('canvas');canvas.width=canvas.height=1080;const ctx=canvas.getContext('2d');ctx.drawImage(background,0,0,1080,1080);background.close();let owned=false;
 try{const path=post.image_paths?.[0]||post.image_path;if(!image&&path&&signedImage){image=await picture(await signedImage(path));owned=true}const layout=artworkLayout(!!image,key,post.artwork_layout);if(image){const box=layout.photo;let crop=null;if(post.artwork_smart_crop!==false)try{crop=faceCrop(image.width,image.height,post.artwork_face?[facePixels(post.artwork_face,image.width,image.height)]:await detectFaces(image),box.width/box.height)}catch{}ctx.save();ctx.fillStyle='#fff';ctx.fillRect(box.x-6,box.y-6,box.width+12,box.height+12);ctx.beginPath();ctx.rect(box.x,box.y,box.width,box.height);ctx.clip();if(crop)ctx.drawImage(image,crop.x,crop.y,crop.width,crop.height,box.x,box.y,box.width,box.height);else{const scale=Math.min(box.width/image.width,box.height/image.height);ctx.drawImage(image,box.x+(box.width-image.width*scale)/2,box.y+(box.height-image.height*scale)/2,image.width*scale,image.height*scale)}ctx.restore()}
 const r=layout.text;ctx.direction='rtl';ctx.textAlign=layout.align||'right';const textX=ctx.textAlign==='left'?r.x:ctx.textAlign==='center'?r.x+r.width/2:r.x+r.width;ctx.textBaseline='top';const label=artworkTypes.find(([k])=>k===key)?.[1];let title=String(post.title||'');if(title===label)title='';let chosen;
 for(let size=42;size>=27;size-=1){ctx.font=`${size}px sans-serif`;const lines=textLines(ctx,post.body,r.width);const titleLines=title?textLines(ctx,title,r.width):[];const lineHeight=Math.round(size*1.55);chosen={lines,titleLines,size,lineHeight};if((lines.length+titleLines.length+0.4)*lineHeight<=r.height)break}
 const{lines,titleLines,size,lineHeight}=chosen;let y=r.y;ctx.fillStyle='#253b47';ctx.font=`bold ${size}px sans-serif`;for(const line of titleLines.slice(0,2)){ctx.fillText(line,textX,y,r.width);y+=lineHeight}if(titleLines.length)y+=12;ctx.font=`${size}px sans-serif`;const max=Math.max(1,Math.floor((r.y+r.height-y)/lineHeight)),visible=lines.slice(0,max);canvas.artworkTruncated=lines.length>max||titleLines.length>2;if(canvas.artworkTruncated)visible[visible.length-1]='التفاصيل كاملة في نص الخبر…';for(const line of visible){ctx.fillText(line,textX,y,r.width);y+=lineHeight}return canvas;
 }finally{if(owned)image?.close()}
}
export async function artworkPreview(parent,post,blob){const version=(parent._artworkVersion||0)+1;parent._artworkVersion=version;let image;try{if(blob)image=await createImageBitmap(blob);const canvas=await newsArtworkCanvas(post,{image});if(version!==parent._artworkVersion)return;parent.querySelector('.news-artwork-preview')?.remove();if(canvas){canvas.className='news-artwork-preview';canvas.setAttribute('role','img');canvas.setAttribute('aria-label','معاينة تصميم الخبر');parent.append(canvas);if(post.artwork_only&&canvas.artworkTruncated){const note=document.createElement('small');note.className='artwork-overflow-note';note.textContent='النص أطول من القالب؛ سيظل النص الكامل ظاهرًا أسفل الخبر. اختصره للاكتفاء بالصورة.';parent.querySelector('.artwork-overflow-note')?.remove();parent.append(note)}else parent.querySelector('.artwork-overflow-note')?.remove()}}finally{image?.close()}}
